def local_image_src(key: str) -> str:
    """Return an inline base64 data URI for st.image()."""
    return f"data:image/png;base64,{_B64[key]}"


# ── Supabase client (lazy-init to avoid module-level side effects) ─────────────
@st.cache_resource
def get_supabase():
    from supabase import create_client
    url = st.secrets["supabase"]["url"]
    key = st.secrets["supabase"]["key"]
    return create_client(url, key)


# ── Data helpers ───────────────────────────────────────────────────────────────

@st.cache_data(ttl=60)
def fetch_history() -> pd.DataFrame:
    """Fetch all daily_tracking rows and return as a DataFrame indexed by date."""
    sb = get_supabase()
    response = sb.table("daily_tracking").select("*").execute()
    rows = response.data or []
    if not rows:
        return pd.DataFrame(columns=["date", "workout", "nutrition", "abs", "jawline", "kegel"])
    df = pd.DataFrame(rows)
    df["date"] = pd.to_datetime(df["date"]).dt.date
    df = df.set_index("date")
    for col in ["workout", "nutrition", "abs", "jawline", "kegel"]:
        if col in df.columns:
            df[col] = df[col].fillna(False).astype(bool)
    return df


def upsert_day(day: date, field: str, value: bool):
    """UPSERT a single boolean field for a given date."""
    sb = get_supabase()
    sb.table("daily_tracking").upsert(
        {"date": str(day), field: value},
        on_conflict="date"
    ).execute()
    fetch_history.clear()          # invalidate cache so next load is fresh


def get_today_row(df: pd.DataFrame, today: date) -> dict:
    """Return today's habit dict (defaults all False if date missing)."""
    defaults = {"workout": False, "nutrition": False, "abs": False,
                "jawline": False, "kegel": False}
    if today in df.index:
        row = df.loc[today]
        return {k: bool(row.get(k, False)) for k in defaults}
    return defaults


# ── Calendar renderer ──────────────────────────────────────────────────────────

def render_calendar(year: int, month: int, df: pd.DataFrame):
    """Render a monthly calendar grid. ✅ = workout done, ⬜ = not done."""
    month_name = calendar.month_name[month]
    st.markdown(f"#### 📆 {month_name} {year}")

    # Header row
    day_names = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
    header_cols = st.columns(7)
    for i, d in enumerate(day_names):
        header_cols[i].markdown(
            f"<div style='text-align:center;font-weight:700;"
            f"font-size:0.75rem;color:#888;letter-spacing:0.08em'>{d}</div>",
            unsafe_allow_html=True,
        )

    # Build weeks
    cal = calendar.Calendar(firstweekday=0)
    weeks = cal.monthdayscalendar(year, month)

    for week in weeks:
        cols = st.columns(7)
        for i, day_num in enumerate(week):
            with cols[i]:
                if day_num == 0:
                    st.markdown("<div style='height:38px'></div>", unsafe_allow_html=True)
                else:
                    d = date(year, month, day_num)
                    worked_out = False
                    if d in df.index:
                        worked_out = bool(df.loc[d, "workout"]) if "workout" in df.columns else False

                    icon = "✅" if worked_out else "⬜"
                    today_style = ""
                    if d == date.today():
                        today_style = "background:#1a2a1a;border-radius:6px;padding:2px 4px;"

                    st.markdown(
                        f"<div style='text-align:center;font-size:0.85rem;"
                        f"{today_style}'>{icon}<br>"
                        f"<span style='font-size:0.7rem;color:#aaa'>{day_num}</span></div>",
                        unsafe_allow_html=True,
                    )


